3363	/// First-occurrence-wins de-duplication by a caller-supplied id, shared by
3364	/// `MeusRegistrosCubit._dedupedById` (paginated `Entry` lists, with an
3365	/// optional running [seenIds] set across pages) and
3366	/// `EntriesRepositoryImpl.search()` (a single `EntryDto` list) — both are
3367	/// trust-but-verify guards against the backend ever violating its own
3368	/// no-duplicate-ids invariant.
3369	List<T> dedupedById<T>(
3370	  List<T> items,
3371	  String Function(T item) idOf, {
3372	  Set<String>? seenIds,
3373	}) {
3374	  final seen = {...?seenIds};
3375	  return [
3376	    for (final item in items)
3377	      if (seen.add(idOf(item))) item,
3378	  ];
3379	}
