3406	/// "no date filter at all", not some maximal range — it resolves to
3407	/// `(null, null)`.
3408	enum DateRangePreset {
3409	  allTime,
3410	  thisWeek,
3411	  thisMonth;
3412	
3413	  String get label => switch (this) {
3414	    DateRangePreset.allTime => 'Todo o período',
3415	    DateRangePreset.thisWeek => 'Esta semana',
3416	    DateRangePreset.thisMonth => 'Este mês',
3417	  };
3418	
3419	  /// This preset's own `(dateFrom, dateTo)` pair, anchored to [now] (a
3420	  /// parameter only so a test can pin it — every real call site passes
3421	  /// `DateTime.now()`). `dateTo` is always [now] itself — "through right
3422	  /// now" — `docs/input/` is silent on inclusive/exclusive bounds here
3423	  /// (AGENTS.md policy: "decide and proceed"). `dateFrom` is local
3424	  /// midnight of the Monday starting this week, or the 1st of this
3425	  /// calendar month.
3426	  (DateTime?, DateTime?) rangeFrom(DateTime now) {
3427	    final today = DateTime(now.year, now.month, now.day);
3428	    switch (this) {
3429	      case DateRangePreset.allTime:
3430	        return (null, null);
3431	      case DateRangePreset.thisWeek:
3432	        return (today.subtract(Duration(days: today.weekday - 1)), now);
3433	      case DateRangePreset.thisMonth:
3434	        return (DateTime(today.year, today.month), now);
3435	    }
3436	  }
3437	}
