3439	/// The reverse of [DateRangePreset.rangeFrom] — which preset (if any) a
3440	/// given [dateFrom] matches, by its own start boundary alone (`dateTo`
3441	/// drifts with "now" on every render, so it's never part of this match).
3442	/// A `null` [dateFrom] (no date filter active) always matches
3443	/// [DateRangePreset.allTime]; shared by this sheet's own pre-selection
3444	/// (reopening with a filter already active) and `MeusRegistrosScreen`'s
3445	/// active-filter chip row (labeling the currently-active range the same
3446	/// way the sheet itself would).
3447	DateRangePreset dateRangePresetMatching(DateTime? dateFrom, DateTime now) {
3448	  if (dateFrom == null) {
3449	    return DateRangePreset.allTime;
3450	  }
3451	  final today = DateTime(now.year, now.month, now.day);
3452	  if (dateFrom == today.subtract(Duration(days: today.weekday - 1))) {
3453	    return DateRangePreset.thisWeek;
3454	  }
3455	  if (dateFrom == DateTime(today.year, today.month)) {
3456	    return DateRangePreset.thisMonth;
3457	  }
3458	  return DateRangePreset.allTime;
3459	}
